/** Символы Amigo — рендерится один раз в корне App; инстансы берут их
 * через <use href="#...">. Клоны наследуют computed-стиль оригинала,
 * поэтому палитра задаётся CSS-классами на символах (styles.css). */
export function AmigoDefs() {
  return (
    <svg width="0" height="0" style={{ position: 'absolute' }} aria-hidden="true">
      <defs>
        {/* Голова (базовая): лицо, каска, фирменные усы-хэндлбар (вверх) */}
        <g id="head-base">
          <path className="ln paper-fill" d="M63 143 q-11 1 -10 13 q1 10 11 7" />
          <path className="ln paper-fill" d="M167 143 q11 1 10 13 q-1 10 -11 7" />
          <path
            className="ln paper-fill"
            d="M64 118 C 58 140 60 162 75 173 C 88 182 102 186 115 186 C 128 186 142 182 155 173 C 170 162 172 140 166 118 C 132 110 98 110 64 118 Z"
          />
          <path
            className="helmet"
            d="M58 110 q1 -56 57 -56 q56 0 57 56 q-28 -10 -57 -10 q-29 0 -57 10 Z"
          />
          <path
            className="helmet-sh"
            d="M58 110 q28 -10 57 -10 q29 0 57 10 q-3 7 -11 6 q-46 -9 -92 0 q-8 1 -11 -6 Z"
          />
          <path className="ln" d="M115 55 q0 27 0 45" opacity=".5" />
          <path className="ln" d="M48 110 q67 -20 134 0" />
          <circle className="fill-ink" cx="92" cy="124" r="6.4" />
          <circle className="fill-ink" cx="138" cy="124" r="6.4" />
          <circle className="hl" cx="94.3" cy="121.7" r="2" />
          <circle className="hl" cx="140.3" cy="121.7" r="2" />
          <path className="ln-thin" d="M111 132 q4 8 4 10 q0 3 5 2" />
          <g className="stache">
            <path id="stache-sil" className="mustache" d={STACHE_D} />
          </g>
          <path className="ln-thin mouth" d="M105 181 q10 6 20 0" />
        </g>
        {/* Неопределённость: бровь поднята, рот — ровная линия (S3) */}
        <g id="head-unc">
          <use href="#head-base" />
          <path className="ln-thin" d="M82 112 q9 -6 18 -1" />
          <path
            d="M103 181 q12 6 24 0"
            fill="none"
            stroke="var(--surface)"
            strokeWidth="8"
            strokeLinecap="round"
          />
          <path className="ln-thin" d="M105 181 q10 -1 20 1" />
        </g>
        {/* Успех: глаза-дуги, шире улыбка (S5 freeze) */}
        <g id="head-suc">
          <use href="#head-base" />
          <circle className="paper-fill" cx="92" cy="124" r="9" />
          <circle className="paper-fill" cx="138" cy="124" r="9" />
          <path className="ln-thin" d="M86 126 q6 -8 12 0" />
          <path className="ln-thin" d="M132 126 q6 -8 12 0" />
        </g>
        {/* Плечи/бюст */}
        <g id="amigo-shoulders">
          <path className="ln paper-fill" d="M56 260 q0 -54 59 -54 q59 0 59 54" />
          <path className="ln-thin" d="M95 214 q20 14 40 0" />
          <path className="ln-thin" d="M115 222 q0 19 0 38" />
          <path className="ln-thin" d="M141 244 q12 -3 18 2" opacity=".65" />
        </g>
      </defs>
    </svg>
  );
}

export type AmigoMood = 'base' | 'unc' | 'suc';

/** Компактная марка (V5): дуга каски + козырёк + глаза + усы. Примитивы
 * инлайн (не через символ), чтобы конкретный инстанс мог спрятать усы:
 * «офлайн = без усов» — CSS не дотягивается внутрь use-клона. */
export function AmigoMark({
  size = 18,
  withStache = true,
}: {
  size?: number;
  withStache?: boolean;
}) {
  return (
    <svg
      className="amigo-mark"
      width={size}
      height={size}
      viewBox="0 0 120 120"
      aria-hidden="true"
    >
      <path className="mk-fill" d="M30 56 A30 30 0 0 1 90 56 Z" />
      <rect className="mk-fill" x="26" y="54" width="68" height="7" rx="3.5" />
      <line className="mk-ridge" x1="60" y1="29" x2="60" y2="54" />
      <circle className="mk-eye" cx="48" cy="74" r="5" />
      <circle className="mk-eye" cx="72" cy="74" r="5" />
      {withStache && (
        <use
          href="#stache-sil"
          transform="translate(-51.62 -62.51) scale(0.9664)"
        />
      )}
    </svg>
  );
}

/** Выразительный бюст — для содержательных моментов (empty-state S1). */
export function AmigoBust({
  mood = 'base',
  width = 110,
}: {
  mood?: AmigoMood;
  width?: number;
}) {
  return (
    <svg width={width} viewBox="0 0 230 260" role="img" aria-label="Amigo">
      <use href="#amigo-shoulders" />
      <g className="head">
        <use href={`#head-${mood}`} />
      </g>
    </svg>
  );
}

/** Голова для tip-плашек (геометрия и спарк — из 08-mockups, S5). */
export function AmigoHead({
  mood = 'base',
  spark = false,
}: {
  mood?: AmigoMood;
  spark?: boolean;
}) {
  return (
    <svg
      className="amigo-head"
      viewBox={spark ? '42 48 146 152' : '46 48 134 152'}
      aria-hidden="true"
    >
      <g className="head">
        <use href={`#head-${mood}`} />
      </g>
      {spark && (
        <g transform="translate(178,62)">
          <path
            className="helmet-sh"
            d="M0 -8 L1.9 -1.9 L8 0 L1.9 1.9 L0 8 L-1.9 1.9 L-8 0 L-1.9 -1.9 Z"
          />
        </g>
      )}
    </svg>
  );
}

/** Плашка-реплика Amigo: периферийная, без модалок (§10.3). */
export function AmigoTip({
  kind,
  mood = 'base',
  spark = false,
  className = '',
  children,
}: {
  /** Акцент-полоса: ok=успех, unc=неопределённость, hint=подсказка. */
  kind?: 'ok' | 'unc' | 'hint';
  mood?: AmigoMood;
  spark?: boolean;
  className?: string;
  children: ReactNode;
}) {
  return (
    <div className={`amigo-tip ${kind ?? ''} ${className}`.trim()}>
      <AmigoHead mood={mood} spark={spark} />
      <div className="bub">{children}</div>
    </div>
  );
}
